1	// Live-mode configuration. The environment is read in exactly one function
2	// (readLiveConfig) and values are passed explicitly from there. Results name
3	// missing variables, never their values.
4	
5	import { PgLiveStore, type PgDb } from "./pg-store";
6	
7	export interface LiveKeys {
8	  readonly crustdataApiKey: string;
9	  readonly llmApiKey: string;
10	  readonly llmBaseUrl: string;
11	  // Optional LIVE_LLM_MODEL; absent means LIVE_RUN_CONFIG.model.
12	  readonly llmModel?: string;
13	}
14	
15	export interface LiveConfig {
16	  readonly databaseUrl: string;
17	  readonly hmacSecret: string;
18	  // null when any live-mode key is missing: synthetic codes still work.
19	  readonly live: LiveKeys | null;
20	  // Names only.
21	  readonly missingLiveKeys: readonly string[];
22	}
23	
24	export type LiveConfigResult =
25	  | { readonly ok: true; readonly config: LiveConfig }
26	  | { readonly ok: false; readonly missing: readonly string[] };
27	
28	type Env = Readonly<Record<string, string | undefined>>;
29	
30	const MODEL_NAME = /^[A-Za-z0-9._:/-]{1,64}$/;
31	
32	function present(value: string | undefined): value is string {
33	  return typeof value === "string" && value.trim() !== "";
34	}
35	
36	export function readLiveConfig(env: Env = process.env): LiveConfigResult {
37	  const databaseUrl = env.DATABASE_URL;
38	  const hmacSecret = env.INVITE_HMAC_SECRET;
39	  const crustdataApiKey = env.CRUSTDATA_LIVE_API_KEY;
40	  const llmApiKey = env.LIVE_LLM_API_KEY;
41	  const llmBaseUrl = env.LIVE_LLM_BASE_URL;
42	  const llmModel = env.LIVE_LLM_MODEL;
43	
44	  const missing: string[] = [];
45	  if (!present(databaseUrl)) missing.push("DATABASE_URL");
46	  if (!present(hmacSecret)) missing.push("INVITE_HMAC_SECRET");
47	  if (!present(databaseUrl) || !present(hmacSecret)) return { ok: false, missing };
48	
49	  const missingLiveKeys: string[] = [];
50	  if (!present(crustdataApiKey)) missingLiveKeys.push("CRUSTDATA_LIVE_API_KEY");
51	  if (!present(llmApiKey)) missingLiveKeys.push("LIVE_LLM_API_KEY");
52	  if (!present(llmBaseUrl)) missingLiveKeys.push("LIVE_LLM_BASE_URL");
53	
54	  // Optional: absent keeps the default model, but a value that is set must be valid.
55	  const modelSet = present(llmModel);
56	  const modelValid = !modelSet || MODEL_NAME.test(llmModel);
57	  if (!modelValid) missingLiveKeys.push("LIVE_LLM_MODEL");
58	
59	  const live =
60	    present(crustdataApiKey) && present(llmApiKey) && present(llmBaseUrl) && modelValid
61	      ? { crustdataApiKey, llmApiKey, llmBaseUrl, ...(modelSet ? { llmModel } : {}) }
62	      : null;
63	  return { ok: true, config: { databaseUrl, hmacSecret, live, missingLiveKeys } };
64	}
