66	// Serverless-sized pool. The managed database may need several seconds to
67	// wake up, hence the 10 s connection timeout. pg is imported lazily so unit
68	// tests never load it. Not called by any test.
69	export async function connectStore(
70	  databaseUrl: string,
71	): Promise<{ store: PgLiveStore; close(): Promise<void> }> {
72	  const { Pool } = await import("pg");
73	  const pool = new Pool({
74	    connectionString: databaseUrl,
75	    max: 3,
76	    connectionTimeoutMillis: 10_000,
77	    idleTimeoutMillis: 10_000,
78	  });
79	  const db: PgDb = {
80	    query: (text, params) => pool.query(text, params),
81	    async transaction(fn) {
82	      const client = await pool.connect();
83	      try {
84	        await client.query("BEGIN");
85	        const out = await fn({ query: (t, p) => client.query(t, p) });
86	        await client.query("COMMIT");
87	        return out;
88	      } catch (err) {
89	        await client.query("ROLLBACK").catch(() => undefined);
90	        throw err;
91	      } finally {
92	        client.release();
93	      }
94	    },
95	  };
96	  return { store: new PgLiveStore(db), close: () => pool.end() };
97	}
