256	async function main(): Promise<void> {
257	  const args = validateRunArgs(parseRunArgs(process.argv.slice(2)), process.env);
258	  const config = args.config === "dev" ? DEV_RUN_CONFIG : EVAL_RUN_CONFIG;
259	  const icp = buildRunIcp(args);
260	  const icp_description =
261	    args.provider === "fixture" ? EVIDENCE_ICP_DESCRIPTION : describeIcp(icp);
262	
263	  const provider = buildProvider(args, config);
264	  const llm = new HashingLlmClient(buildLlm(args.llm));
265	  const searched: RawCompany[] = [];
266	  const spend: ProviderSpend = { search: 0, enrich: 0 };
267	  const recordingProvider: CompanyProvider = {
268	    autocompleteIndustry: (query) => provider.autocompleteIndustry(query),
269	    async enrichCompanies(urls) {
270	      const res = await provider.enrichCompanies(urls);
271	      if (res.ok) spend.enrich += res.cost_usd;
272	      return res;
273	    },
274	    async searchCompanies(filters, limit) {
275	      const res = await provider.searchCompanies(filters, limit);
276	      if (res.ok) {
277	        searched.push(...res.data);
278	        spend.search += res.cost_usd;
279	      }
280	      return res;
281	    },
282	  };
283	  const started_at = new Date().toISOString();
284	
285	  const result = await withTracing(args, (tracer) => {
286	    const deps = { provider: recordingProvider, budget: provider.budget, llm, tracer };
287	    return args.pipeline === "baseline"
288	      ? runBaselinePipeline(icp, deps, { config })
289	      : runImprovedPipeline(icp, { ...deps, fact_provider: args.provider }, { config });
290	  });
291	
292	  const system_prompt_hashes = [...llm.system_hashes].sort();
293	  const validation = postHocValidation(searched, result);
294	  const finalVal = finalValidation(searched, result);
295	  const report = buildReport(args, config, icp_description, result, started_at, { system_prompt_hashes }, validation, finalVal, spend);
296	  await mkdir("runs", { recursive: true });
297	  const path = `runs/${started_at.replace(/[:.]/g, "-")}-${fileSafe(args.label)}.json`;
298	  await writeFile(path, `${JSON.stringify(report, null, 2)}\n`);
299	
300	  const { counts, cost_usd_by_step: cost } = result.run;
301	  const llmCost = result.usage.llm_cost;
302	  const costBasis = args.provider === "fixture" ? "simulated at measured Crustdata prices" : "measured";
303	  console.log(`run ${result.run.trace_id}  status=${result.status}  label=${args.label}`);
304	  console.log(
305	    `setup    pipeline=${args.pipeline} provider=${args.provider} fact_provider=${args.provider} tracing=${args.tracing ? "on" : "off"}` +
306	      ` search_sort=${args.provider === "fixture" ? "none" : `${CRUSTDATA_SEARCH_SORT.field} ${CRUSTDATA_SEARCH_SORT.order}`}`,
307	  );
308	  console.log(
309	    `counts   searched=${counts.searched} enriched=${counts.enriched} delivered=${counts.delivered} llm_calls=${counts.llm_calls}`,
310	  );
311	  console.log(`tokens   in=${counts.llm_input_tokens} out=${counts.llm_output_tokens}  (${tokenBasis(args.llm)})`);
312	  console.log(
313	    `provider search=$${cost.search.toFixed(3)} enrich=$${cost.enrich.toFixed(3)}  (${costBasis}; provider-returned total=$${(spend.search + spend.enrich).toFixed(3)})`,
314	  );
315	  console.log(
316	    `llm      gateway_reported=$${llmCost.gateway_reported_usd.toFixed(4)} (${llmCost.calls_by_basis.gateway_reported} calls)` +
317	      `  estimated=$${llmCost.estimated_usd.toFixed(4)} (${llmCost.calls_by_basis.estimated} calls)` +
318	      `  unavailable=${llmCost.calls_by_basis.unavailable} calls`,
319	  );
320	  console.log(
321	    `prompt   version=${PROMPT_VERSION} safety_rules_sha256=${sha256Hex(PROMPT_SAFETY_RULES).slice(0, 12)} system_hashes=${system_prompt_hashes.join(",") || "none"}`,
322	  );
323	  const fmt = (c: { valid: number; flagged: number; rejected: number }) =>
324	    `valid=${c.valid} flagged=${c.flagged} rejected=${c.rejected}`;
325	  console.log("post-hoc validation (counts)");
326	  console.log(`  searched  ${fmt(validation.searched)}`);
327	  console.log(`  enriched  ${fmt(validation.enriched)}  wasted_enrichments=${validation.wasted_enrichments}`);
328	  console.log(`  delivered ${fmt(validation.delivered)}  duplicate_groups=${validation.delivered_duplicate_groups}`);
329	  const tally = (r: Readonly<Record<string, number>>) =>
330	    Object.entries(r)
331	      .map(([key, n]) => `${key}=${n}`)
332	      .join(",") || "none";
333	  console.log("final-record validation (counts)");
334	  console.log(`  all       ${fmt(finalVal.all)}`);
335	  console.log(`  assessed  ${fmt(finalVal.assessed)}`);
336	  console.log(`  issues    ${tally(finalVal.issues_by_code_field)}`);
337	  console.log(
338	    `  changed_by_enrichment=${finalVal.changed_by_enrichment.count} (${tally(finalVal.changed_by_enrichment.transitions)})` +
339	      ` ids=${finalVal.changed_by_enrichment.company_ids.join(",") || "none"}`,
340	  );
341	  const m = computeBaselineCitationMetrics(result, args.provider);
342	  if (args.pipeline === "baseline") {
343	    console.log(
344	      `citations assessed=${m.assessed} drafts=${m.outreach_drafts} cited=${m.cited_fact_ids} citeable=${m.citeable} missing=${m.missing}` +
345	        ` cross_company=${m.cross_company} model_provider=${m.model_provider} uncertain=${m.uncertain}` +
346	        ` other_non_citeable=${m.other_non_citeable} drafts_with_violations=${m.drafts_with_violations.count}`,
347	    );
348	  } else if (result.metrics) {
349	    const im = result.metrics;
350	    console.log(
351	      `improved rejected=${im.rejected.count} flagged=${im.flagged.count} duplicates_removed=${im.duplicates_removed.count}` +
352	        ` eligible=${im.enrichment.eligible.count} requested=${im.enrichment.requested.count} enriched=${im.enrichment.enriched.count}` +
353	        ` assessments_failed=${im.assessments_failed.count} outreach_suppressed=${im.outreach_suppressed.count}` +
354	        ` claim_violations=${im.claim_violations.count} (drafts=${im.claim_violations.drafts})`,
355	    );
356	    const g = summarizeGuardFindings(result.prospects, im);
357	    const byCode = (r: Readonly<Record<string, number>>) =>
358	      Object.entries(r)
359	        .map(([code, n]) => `${code}=${n}`)
360	        .join(",") || "none";
361	    console.log(`guards   findings: ${byCode(g.findings_by_code)}  claim_violations: ${byCode(g.claim_violations_by_code)}`);
362	  } else {
363	    console.log("improved metrics unavailable (the run stopped before validation)");
364	  }
365	  console.log(formatOutreachLine(summarizeOutreachKept(result.prospects), m));
366	  console.log(`issues   ${result.issues.map((i) => i.code).join(", ") || "none"}`);
367	  console.log(`report   ${path}`);
368	  if (result.status === "stopped") {
369	    console.error("The run stopped early; see the issue codes above.");
370	  }
371	  process.exitCode = exitCodeForStatus(result.status);
372	}
373	
374	main().catch((err) => {
375	  console.error(
376	    err instanceof UsageError ? err.message : `Run failed: ${err instanceof Error ? err.message : "unknown error"}`,
377	  );
378	  process.exitCode = exitCodeForError(err);
379	});
