1	// Presentation DTO for the live beta, for both synthetic and live codes.
2	// Built field by field from an improved-pipeline result: nothing is spread
3	// from pipeline objects, and every displayed message is fixed text chosen by
4	// code (see safe-text.ts). It reuses the results page's ProspectDto and
5	// MetricsDto without changing ResultsDto or toResultsDto.
6	//
7	// Its signature matches the server's injected results mapper:
8	// (result, { mode, model }) => results.
9	
10	import type { LlmCostSummary, PipelineResult, PipelineStatus } from "../../../core/agent/types";
11	import {
12	  type MetricsDto,
13	  metricsDto,
14	  type ProspectDto,
15	  toProspectDto,
16	} from "../../results/_lib/presentation";
17	import { issueMessage, safeCode, safeProspect } from "./safe-text";
18	
19	export type LiveMode = "synthetic" | "live";
20	
21	export interface LiveResultsContext {
22	  readonly mode: LiveMode;
23	  // The model the run used: the fake model's name in synthetic mode.
24	  readonly model: string;
25	}
26	
27	// How the provider cost was arrived at.
28	// simulated_fixture_prices: synthetic mode. FixtureProvider's per-record
29	//   prices; nothing was called or charged.
30	// estimated_per_record: live mode. Records searched and enriched, priced at
31	//   the measured per-record rates. An estimate, not an invoice.
32	export type ProviderCostBasis = "simulated_fixture_prices" | "estimated_per_record";
33	
34	// What kind of known model cost model_usd holds, from llm_cost.calls_by_basis.
35	// It describes the known costs only; completeness is model_complete's job.
36	// none: no external model cost. No model calls in live mode; always in
37	//   synthetic mode, whose fake-model calls call no external model.
38	// gateway_reported: every known cost was reported by the gateway.
39	// estimated: every known cost was estimated from token usage at the
40	//   fallback rates.
41	// mixed: known costs of both kinds.
42	// unavailable: model calls were made but no call has a known cost.
43	export type ModelCostBasis = "none" | "gateway_reported" | "estimated" | "mixed" | "unavailable";
44	
45	export interface LiveCostDto {
46	  readonly provider_usd: number;
47	  readonly provider_basis: ProviderCostBasis;
48	  // The known model cost, usage.llm_cost.known_usd, as reported (0 in
49	  // synthetic mode). Read it with model_basis and model_complete: 0 with
50	  // basis "unavailable" means unknown, not free.
51	  readonly model_usd: number;
52	  readonly model_basis: ModelCostBasis;
53	  // True only when every model call has a known cost (and when there were
54	  // none). When false, model_usd is a lower bound, never a total.
55	  readonly model_complete: boolean;
56	  // Model calls whose cost is not known, including calls the basis counts
57	  // fail to account for.
58	  readonly model_calls_unavailable: number;
59	}
60	
61	export interface LiveResultsDto {
62	  readonly run: {
63	    readonly status: PipelineStatus;
64	    readonly mode: LiveMode;
65	    readonly data_source: "fixtures" | "crustdata";
